const path=location.pathname,view=document.querySelector('#view'),nav=document.querySelector('#appNav'),requestedCompanyId=new URLSearchParams(location.search).get('company')||'autopilots',unauthenticatedRoutes=new Set(['/login','/auth/callback']);let data=null,viewer=null,osData=null,selectedCompanyId=requestedCompanyId,loginRole='customer',authCapabilities={provider:'demo',magicLink:false},pendingMfa=null;
if(path==='/login'){const capabilityResponse=await fetch('/api/v1/session/capabilities');if(capabilityResponse.ok)authCapabilities=await capabilityResponse.json()}
if(!unauthenticatedRoutes.has(path)){const sessionResponse=await fetch('/api/v1/session');if(sessionResponse.status===401)location.replace('/login');else if(!sessionResponse.ok)throw new Error('Sessie kon niet worden geladen');else{viewer=(await sessionResponse.json()).user;if(viewer.role==='internal'&&!viewer.companies.some(company=>company.id===selectedCompanyId))selectedCompanyId=viewer.companies[0].id;const dataCompany=viewer.role==='internal'?selectedCompanyId:'autopilots';const dataResponse=await fetch(`/api/v1/demo?company=${encodeURIComponent(dataCompany)}`);if(!dataResponse.ok)throw new Error('Werkruimte kon niet worden geladen');data=await dataResponse.json();if(viewer.role==='internal'){const osEndpoint=path==='/control-center/portfolio'?'/api/v1/os/portfolio':`/api/v1/os/brands/${encodeURIComponent(dataCompany)}`;const osResponse=await fetch(osEndpoint);if(!osResponse.ok)throw new Error('OS Digital Twin kon niet worden geladen');osData=await osResponse.json()}}}
const customerNav=[['/','Overzicht'],['/demo','Jouw AI Medewerker'],['/requirements','Inzichten'],['/voorstel','Voorstel'],['/documenten','Voorwaarden'],['/secure-data-room','Veilige onboarding'],['/integraties','Koppelingen'],['/testen','Testen'],['/activiteit','Activiteit']];const adminNav=[['/control-center/portfolio','Portfolio'],['/control-center','Overzicht'],['/control-center/implementaties/impl_001','Implementatie'],['/control-center/tasks','Menselijke taken'],['/control-center/approvals','Approvals'],['/control-center/agents','Agent Control Room']];
const internal=viewer?.role==='internal',activeCompany=internal?(viewer?.companies?.find(company=>company.id===selectedCompanyId)||viewer?.companies?.[0]):null,companyApiQuery=`company=${encodeURIComponent(activeCompany?.id||'autopilots')}`;if(!unauthenticatedRoutes.has(path)){document.body.classList.toggle('internal-mode',internal);const companySuffix=internal?`?${companyApiQuery}`:'';nav.innerHTML=(internal?adminNav:customerNav).map(([href,label],index)=>`<a href="${href}${companySuffix}" class="${path===href?'active':''}"><i aria-hidden="true">${String(index+1).padStart(2,'0')}</i><span>${label}</span></a>`).join('');const workspace=document.querySelector('.workspace');if(internal){document.querySelector('.ap-brand').href=`/control-center/portfolio?${companyApiQuery}`;const companyMark=activeCompany.code||activeCompany.name.slice(0,2).toUpperCase();workspace.innerHTML=`<button class="company-trigger" type="button" data-action="company-toggle" aria-expanded="false"><span class="company-mark">${companyMark}</span><span><small>OPERATING BRAND</small><strong>${activeCompany.name}</strong></span><i aria-hidden="true">⌄</i></button><div class="company-menu" hidden>${viewer.companies.map(company=>`<button type="button" data-action="company-select" data-id="${company.id}" class="${company.id===activeCompany.id?'active':''}"><span>${company.name}</span><small>${company.status==='active'?'Actief':'Foundation'}</small></button>`).join('')}</div>`}else{document.querySelector('#spaceLabel').textContent='WERKOMGEVING';document.querySelector('#spaceName').textContent=data.organization.name}document.querySelector('.avatar').textContent=viewer.name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();document.querySelector('.reset-link').hidden=!internal||activeCompany.id!=='autopilots';if(internal){document.querySelector('.status').innerHTML=`<span class="status-core" aria-hidden="true"></span><span><b>OS ONLINE</b><small>${viewer.mfaRequired&&!viewer.mfaSatisfied?'MFA vereist voor acties':'Read-only control plane'}</small></span>`;document.querySelector('.notice').hidden=true}}
const badge=(text,type='')=>`<span class="badge ${type}">${text}</span>`,head=(eyebrow,title,copy,actions='')=>`<section class="view-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${copy}</p></div><div class="actions">${actions}</div></section>`,button=(label,action,id='',kind='secondary')=>`<button class="button ${kind}" data-action="${action}" data-id="${id}">${label}</button>`;
function render(){if(path==='/auth/callback')return authCallback();if(path==='/login')return login();if(internal&&path==='/control-center/portfolio')return portfolio();if(internal&&data.empty)return companyTwin();if(path==='/')return overview();if(path==='/demo')return demo();if(path==='/requirements')return requirements();if(path==='/voorstel')return proposal();if(path==='/documenten')return documents();if(path==='/afrekenen')return checkout();if(path==='/betaling-geslaagd')return paid();if(path==='/onboarding'||path==='/secure-data-room')return secureDataRoom();if(path==='/integraties')return integrations();if(path==='/testen')return tests();if(path==='/activiteit')return activity();if(path==='/control-center')return control();if(path==='/control-center/tasks')return tasks();if(path==='/control-center/approvals')return approvals();if(path==='/control-center/agents')return agents();if(path.startsWith('/control-center/implementaties/'))return implementation();}
