const workflowRadar=()=>{const customerCount=data.organization?1:0,implementationCount=data.implementation?.status==='active'?1:0;return`<section class="command-deck"><article class="radar-panel"><div class="radar-visual portfolio-radar"><div class="radar-sweep"></div><div class="radar-core"><strong>${customerCount}</strong><span>KLANTEN</span></div><i class="orbit-node node-a"></i><i class="orbit-node node-b"></i><i class="orbit-node node-c"></i></div><div class="radar-copy"><span class="metric-label">CUSTOMER NETWORK</span><h2>${customerCount} actieve organisatie</h2><p>${implementationCount} implementatie in delivery · sandboxportfolio</p></div></article><article class="telemetry-panel"><div class="telemetry-head"><div><span class="metric-label">SYSTEM ACTIVITY</span><strong>${data.executions.length} executions</strong></div>${badge(data.preview.externalWrites?'Writes actief':'Writes geblokkeerd',data.preview.externalWrites?'orange':'green')}</div>${signalBars()}<div class="telemetry-grid"><span><b>${data.agents.filter(agent=>agent.status==='running').length}</b> agents actief</span><span><b>${data.integrations.filter(item=>item.health==='healthy').length}</b> koppelingen gezond</span><span><b>${data.metrics.humanAttention}</b> menselijke acties</span></div></article></section>`};
const workflowVector=()=>`<section class="workflow-vector" aria-label="Workflowstatus"><div class="vector-line"></div>${[['01','Preview'],['02','Legal'],['03','Activation'],['04','Approval']].map(([number,label],index)=>`<div class="vector-node ${stageState(index)}"><i>${number}</i><span>${label}</span></div>`).join('')}</section>`;
function portfolio(){const totals=osData.brands.reduce((summary,brand)=>({customers:summary.customers+brand.customerCount,exceptions:summary.exceptions+brand.openExceptionCount}),{customers:0,exceptions:0});view.innerHTML=head('PORTFOLIO COMMAND',`${osData.legalEntity.legalName} <em>in één bestuurbaar beeld.</em>`,'Selecteer een operating brand om doelen, klanten, bronnen, kosten, risico en bewijs binnen de juiste scope te bekijken.',badge('Read-only foundation','green'))+`<section class="grid metrics hud-metrics"><article class="metric"><span class="metric-label">Operating brands</span><strong>${osData.brands.length}</strong><small>onder één legal entity</small></article><article class="metric"><span class="metric-label">Klantaccounts</span><strong>${totals.customers}</strong><small>waarvan demo-gelabeld</small></article><article class="metric"><span class="metric-label">Owner exceptions</span><strong>${totals.exceptions}</strong><small>materiële uitzonderingen</small></article><article class="metric"><span class="metric-label">Geblokkeerde bronnen</span><strong>${osData.dataHealth.blocked}</strong><small>geen live claims mogelijk</small></article></section><section class="os-section"><div class="os-section-head"><div><span class="metric-label">OPERATING BRANDS</span><h2>Portfolio-overzicht</h2></div><p>Financiële waarden blijven onbekend totdat een gezaghebbende bron is gekoppeld en gereconcilieerd.</p></div><div class="brand-grid">${osData.brands.map(brand=>`<a class="brand-tile" href="/control-center?company=${brand.slug}"><span class="company-mark">${brand.code}</span><div><small>${brand.status==='active'?'ACTIEF':'FOUNDATION'}</small><h3>${brand.name}</h3><p>${brand.customerCount} klanten · ${brand.goalCount} doelen · ${brand.openExceptionCount} exceptions</p></div><i aria-hidden="true">→</i></a>`).join('')}</div></section><section class="os-section"><div class="os-section-head"><div><span class="metric-label">SOURCE CONTROL</span><h2>Datakwaliteit</h2></div>${badge(`${osData.dataHealth.blocked} geblokkeerd`,'orange')}</div><div class="source-grid">${osData.sourceOfTruth.map(source=>sourceRow(source)).join('')}</div></section>`}
function companyTwin(){const brand=osData.brand,goal=osData.goals[0],lifecycle=osData.lifecycles[0],finance=osData.finance,health=osData.dataHealth,operations=osData.operations,customerCount=operations?.status==='connected'?operations.snapshot.customerPlatform.organizations:osData.customers.length;view.innerHTML=head(`${brand.name.toUpperCase()} COMMAND`,`${brand.name} Digital Twin <em>zonder schijnzekerheid.</em>`,'Doelen, lifecycle, bronnen, kosten en uitzonderingen binnen één expliciete operating-brand-scope.',badge(brand.status==='active'?'Actief':'Foundation',brand.status==='active'?'green':'orange'))+`<section class="scope-strip"><span><small>LEGAL ENTITY</small><b>${osData.legalEntity.legalName}</b></span><span><small>OPERATING BRAND ID</small><b>${brand.id}</b></span><span><small>ENVIRONMENT</small><b>${osData.scope.environment}</b></span><span><small>GENERATED</small><b>${new Date(osData.generatedAt).toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'})}</b></span></section><section class="grid metrics hud-metrics"><article class="metric"><span class="metric-label">Klanten</span><strong>${customerCount}</strong><small>${operations?.status==='connected'?'uit AutoReviews SaaS':'expliciet gemapte accounts'}</small></article><article class="metric"><span class="metric-label">Omzet</span><strong class="metric-unknown">${formatKnownMoney(finance.revenueCents)}</strong><small>${finance.quality}</small></article><article class="metric"><span class="metric-label">Gemeten kosten</span><strong>${formatMoney(finance.measuredCostCents)}</strong><small>${finance.entryCount} ledgerregels</small></article><article class="metric"><span class="metric-label">Brongezondheid</span><strong>${health.healthy}/${health.totalSources}</strong><small>${health.blocked} koppelingen geblokkeerd</small></article></section><section class="twin-grid"><article class="twin-panel"><span class="metric-label">OWNER GOAL</span><div class="twin-panel-title"><h2>${goal?.title||'Nog geen doel vastgesteld'}</h2>${badge(goal?.status||'open','orange')}</div><p>${goal?.target===null?'Baseline en target wachten op betrouwbare brondata.':'Doel is gekwantificeerd en meetbaar.'}</p><dl><div><dt>KPI</dt><dd>${goal?.kpi||'Niet toegewezen'}</dd></div><div><dt>Owner</dt><dd>${goal?.owner||'Niet toegewezen'}</dd></div><div><dt>Bewijs vereist</dt><dd>${goal?.evidenceRequired?'Ja':'Nee'}</dd></div></dl></article><article class="twin-panel"><span class="metric-label">FINOPS TRUTH</span><div class="twin-panel-title"><h2>Financiële kwaliteit</h2>${badge(finance.quality,'orange')}</div><p>${finance.reason}</p><dl><div><dt>Revenue</dt><dd>${formatKnownMoney(finance.revenueCents)}</dd></div><div><dt>Allocated cost</dt><dd>${formatKnownMoney(finance.allocatedCostCents)}</dd></div><div><dt>Margin</dt><dd>${formatKnownMoney(finance.marginCents)}</dd></div></dl></article></section>${autoreviewsOperations(operations)}<section class="os-section"><div class="os-section-head"><div><span class="metric-label">LIGHTHOUSE WORKFLOW</span><h2>AutoReviews klantlevenscyclus</h2></div>${badge(lifecycle?.status||'niet geconfigureerd','orange')}</div>${lifecycle?`<div class="lifecycle-track">${lifecycle.stages.map((stage,index)=>`<span><i>${String(index+1).padStart(2,'0')}</i>${stage.replaceAll('_',' ')}</span>`).join('')}</div><p class="section-note">Externe writes: ${lifecycle.externalWrites?'toegestaan':'geblokkeerd'} · versie ${lifecycle.version}</p>`:'<div class="honest-empty">Geen lifecycle voor deze brand geconfigureerd.</div>'}</section><section class="os-section"><div class="os-section-head"><div><span class="metric-label">INTEGRATION REGISTRY</span><h2>Bronnen en reconciliation</h2></div>${badge(`${health.blocked} geblokkeerd`,'orange')}</div><div class="source-grid">${osData.integrations.length?osData.integrations.map(connection=>sourceRow({provider:connection.provider,dataClass:connection.provider,authority:'Externe bron',status:connection.status,freshnessExpectation:connection.lastSuccessfulSyncAt?new Date(connection.lastSuccessfulSyncAt).toLocaleString('nl-NL'):'Nog nooit gesynchroniseerd',reconciliationStatus:connection.reconciliationStatus})).join(''):'<div class="honest-empty">Geen externe bronnen voor deze brand geregistreerd.</div>'}</div></section><section class="os-section"><div class="os-section-head"><div><span class="metric-label">OWNER EXCEPTION INBOX</span><h2>Alleen materiële uitzonderingen</h2></div><span>${osData.ownerExceptions.length} open</span></div>${osData.ownerExceptions.length?osData.ownerExceptions.map(exception=>`<article class="exception-row"><span>${exception.severity}</span><div><h3>${exception.title}</h3><p>${exception.consequence}</p><small>Volgende actie: ${exception.nextAction}</small></div>${badge(exception.requiresOwnerDecision?'Besluit vereist':'Operationeel','orange')}</article>`).join(''):'<div class="honest-empty">Geen owner exceptions binnen deze brand scope.</div>'}</section>`}
function autoreviewsOperations(connection){if(!connection)return'';if(connection.status!=='connected')return`<section class="os-section operations-degraded"><div class="os-section-head"><div><span class="metric-label">AUTOREVIEWS BACKEND</span><h2>Website-backend niet bereikbaar</h2></div>${badge('Degraded','orange')}</div><p>De Digital Twin blijft beschikbaar, maar operationele website- en SaaS-cijfers kunnen nu niet worden ververst. Foutcode: ${connection.errorCode}.</p></section>`;const snapshot=connection.snapshot,a=snapshot.acquisition,c=snapshot.customerPlatform,o=snapshot.outbound;return`<section class="os-section"><div class="os-section-head"><div><span class="metric-label">AUTOREVIEWS OPERATIONS</span><h2>Website, acquisitie en klantplatform</h2></div>${badge('Backend gekoppeld','green')}</div><div class="operations-grid"><article><span>Acquisitie</span><b>${a.leads}</b><small>leads</small><dl><div><dt>Scans</dt><dd>${a.scans}</dd></div><div><dt>Voltooid</dt><dd>${a.scansByStatus.completed||0}</dd></div><div><dt>Meetings</dt><dd>${a.meetings}</dd></div><div><dt>Onboarding</dt><dd>${a.onboarding}</dd></div></dl></article><article><span>Klantplatform</span><b>${c.organizations}</b><small>organisaties</small><dl><div><dt>Vestigingen</dt><dd>${c.locations}</dd></div><div><dt>Contacten</dt><dd>${c.contacts}</dd></div><div><dt>Campagnes</dt><dd>${c.campaigns}</dd></div><div><dt>Enrollments</dt><dd>${c.enrollments}</dd></div></dl></article><article><span>Delivery</span><b>${c.messages}</b><small>berichten</small><dl><div><dt>Subscriptions</dt><dd>${c.subscriptions}</dd></div><div><dt>Sent</dt><dd>${c.messageStatus.sent||0}</dd></div><div><dt>Failed</dt><dd>${c.messageStatus.failed||0}</dd></div><div><dt>Usage types</dt><dd>${c.usageByType.length}</dd></div></dl></article><article><span>Outbound</span><b>${o.campaigns}</b><small>campagnes</small><dl><div><dt>Recipients</dt><dd>${o.recipients}</dd></div><div><dt>Approved</dt><dd>${o.approvedRecipients}</dd></div><div><dt>Sent</dt><dd>${o.sent}</dd></div><div><dt>Failed</dt><dd>${o.failed}</dd></div></dl></article></div><p class="section-note">Aggregate no-PII snapshot · ${snapshot.environment} · bijgewerkt ${new Date(snapshot.generatedAt).toLocaleString('nl-NL')}</p></section>`}
function sourceRow(source){const reconciliation=String(source.reconciliationStatus),blocked=reconciliation.startsWith('blocked'),pending=reconciliation.startsWith('awaiting');return`<article class="source-row"><span class="source-node ${blocked?'blocked':pending?'pending':'healthy'}"></span><div><strong>${source.provider}</strong><small>${source.dataClass}</small></div><div><small>AUTHORITATIVE</small><b>${source.authority}</b></div><div><small>FRESHNESS</small><b>${source.freshnessExpectation}</b></div>${badge(blocked?'Geblokkeerd':pending?'Reconciliation':source.status,blocked||pending?'orange':'green')}</article>`}
function login(){document.querySelector('.sidebar').hidden=true;document.querySelector('.topbar').hidden=true;document.querySelector('.notice').hidden=true;document.querySelector('.shell').style.gridTemplateColumns='1fr';const managed=authCapabilities.provider==='supabase';view.innerHTML=`<section class="login-page"><div class="login-story"><img src="/ap-logo.svg" alt="Autopilots"><h1>Welkom in jullie <em>AI-omgeving.</em></h1><p>Beheer Autopilots, AutoReviews, AutoPlanner en RoofPlanner vanuit één beveiligde omgeving.</p></div><div class="login-panel"><div class="eyebrow">${managed?'CENTRALE TOEGANG':'VEILIGE DEMO'}</div><h2>Inloggen bij Autopilots</h2>${managed?'':'<div class="role-switch"><button class="active" type="button" data-action="login-role" data-id="customer">Klant</button><button type="button" data-action="login-role" data-id="internal">Intern team</button></div>'}<form class="login-form" id="loginForm"><div class="field"><label for="demoEmail">E-mailadres</label><input id="demoEmail" type="email" value="${managed?'': 'demo@curacao-auto.example'}" autocomplete="username" required></div>${managed?'':'<div class="field"><label for="demoCode">Democode</label><input id="demoCode" type="password" value="autopilots-demo" autocomplete="current-password" required></div>'}<p class="form-error" id="loginError" role="alert" hidden></p><button class="button" type="submit">${managed?'Stuur beveiligde inloglink':'Open veilige demo'}</button><span class="mini">${managed?'Alleen vooraf geautoriseerde accounts krijgen toegang. Acties vereisen tweestapsverificatie.':'Dit is een geïsoleerde demo. Er worden geen echte account- of betaalgegevens gebruikt.'}</span></form></div></section>`}
async function authCallback(){document.querySelector('.sidebar').hidden=true;document.querySelector('.topbar').hidden=true;document.querySelector('.notice').hidden=true;document.querySelector('.shell').style.gridTemplateColumns='1fr';view.innerHTML=`<section class="login-page"><div class="login-story"><img src="/ap-logo.svg" alt="Autopilots"><h1>Toegang wordt <em>geverifieerd.</em></h1><p>We controleren account, rol, bedrijfsscope en beveiligingsniveau.</p></div><div class="login-panel"><div class="eyebrow">BEVEILIGDE CALLBACK</div><h2 id="callbackTitle">Even geduld…</h2><p id="callbackMessage">De inloglink wordt eenmalig gecontroleerd.</p></div></section>`;const params=new URLSearchParams(location.hash.slice(1)),accessToken=params.get('access_token'),refreshToken=params.get('refresh_token'),errorMessage=params.get('error_description')||new URLSearchParams(location.search).get('error_description');history.replaceState({},document.title,'/auth/callback');try{if(errorMessage)throw new Error(errorMessage);if(!accessToken||!refreshToken)throw new Error('Deze inloglink bevat geen geldige sessie of is verlopen.');const response=await fetch('/api/v1/session/exchange',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accessToken})});const result=await response.json();if(response.status===409&&result.mfaRequired){pendingMfa={accessToken,refreshToken,factorId:null};const preparedResponse=await fetch('/api/v1/session/mfa/prepare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accessToken,refreshToken})});const prepared=await preparedResponse.json();if(!preparedResponse.ok)throw new Error(prepared.error||'Tweestapsverificatie kon niet worden voorbereid.');if(prepared.mode==='complete')return location.replace('/control-center/portfolio');pendingMfa.factorId=prepared.factorId;return renderMfa(prepared)}if(!response.ok)throw new Error(result.error||'De accountrechten konden niet worden geladen.');location.replace('/control-center/portfolio')}catch(error){pendingMfa=null;document.querySelector('#callbackTitle').textContent='Inloggen niet gelukt';document.querySelector('#callbackMessage').innerHTML=`${escapeText(error.message)} <a class="text-link" href="/login">Vraag een nieuwe inloglink aan</a>`}}
function renderMfa(prepared){const enrolling=prepared.mode==='enroll',qr=typeof prepared.qrCode==='string'&&prepared.qrCode.startsWith('data:image/svg+xml')?prepared.qrCode:'';document.querySelector('.login-panel').innerHTML=`<div class="eyebrow">TWEE-STAPSVERIFICATIE</div><h2>${enrolling?'Beveilig je owner-account':'Bevestig je authenticator'}</h2><p>${enrolling?'Scan deze QR-code met je authenticator-app en vul daarna de zescijferige code in.':'Vul de actuele zescijferige code uit je authenticator-app in.'}</p>${enrolling&&qr?'<img id="mfaQr" alt="QR-code voor authenticator" style="width:220px;max-width:100%;background:#fff;padding:12px;border-radius:12px">':''}${enrolling&&prepared.secret?`<p class="mini">Handmatig instellen: <code>${escapeText(prepared.secret)}</code></p>`:''}<form class="login-form" id="mfaForm"><div class="field"><label for="mfaCode">Authenticatorcode</label><input id="mfaCode" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></div><p class="form-error" id="mfaError" role="alert" hidden></p><button class="button" type="submit">Bevestig en open Autopilots</button><span class="mini">De tijdelijke Supabase-sessie blijft alleen in het geheugen van dit tabblad.</span></form>`;const qrImage=document.querySelector('#mfaQr');if(qrImage)qrImage.src=qr}
function escapeText(value){const node=document.createElement('span');node.textContent=String(value);return node.innerHTML}
function overview(){const p=selectedProduct(),confirmed=data.requirements.filter(x=>x.status==='confirmed').length;view.innerHTML=head('KLANTOVERZICHT',`Jullie ${p.name} staat <em>klaar om te testen.</em>`,data.understanding.summary,`<a class="button" href="/demo">Open persoonlijke agent</a>`)+`<section class="grid metrics"><article class="metric"><span class="metric-label">VOORGESTELDE ROL</span><strong class="metric-word">${p.name}</strong><small>Gebaseerd op Consult A + B</small></article><article class="metric"><span class="metric-label">BEGREPEN</span><strong>${confirmed}/${data.requirements.length}</strong><small>requirements bevestigd</small></article><article class="metric"><span class="metric-label">STATUS</span><strong class="metric-word">Preview gereed</strong><small>veilig en geïsoleerd</small></article><article class="metric"><span class="metric-label">VOLGENDE STAP</span><strong class="metric-word">Voorstel</strong><small>controleren en activeren</small></article></section><section class="page-grid two dashboard-row"><article class="card"><div class="card-head"><div><div class="eyebrow">DIT HEBBEN WE BEGREPEN</div><h2>Van gesprek naar inrichting</h2></div><a class="text-link" href="/requirements">Bekijk alles →</a></div>${insightRows(data.understanding.challenges.slice(0,3))}</article><article class="card"><div class="card-head"><div><div class="eyebrow">JULLIE SYSTEEM</div><h2>${p.name}</h2></div>${badge('Preview gereed','green')}</div><p class="muted">${p.promise}</p>${p.capabilities.slice(0,3).map(x=>`<div class="micro-row"><span>✓</span>${x}</div>`).join('')}<div class="actions"><a class="button" href="/demo">Test de agent</a><a class="button secondary" href="/voorstel">Bekijk voorstel</a></div></article></section><section class="card product-section"><div class="card-head"><div><div class="eyebrow">AUTOPILOTS PRODUCTEN</div><h2>Jullie aanbevolen route en uitbreidingen</h2></div><span class="mini">Vaste producten · persoonlijk ingericht</span></div><div class="product-grid">${data.products.map(productCard).join('')}</div></section>`}
function insightRows(items){return `<div class="insight-list">${items.map((x,i)=>`<div class="insight-row"><span>${String(i+1).padStart(2,'0')}</span><strong>${x}</strong></div>`).join('')}</div>`}
function productCard(p){return `<article class="product-card ${p.recommended?'recommended':''}"><span class="metric-label">${p.eyebrow}</span><h3>${p.name}</h3><p>${p.promise}</p><div class="channel-list">${p.channels.map(x=>`<span>${x}</span>`).join('')}</div>${p.recommended?badge('Passend bij consult','green'):''}</article>`}
function demo(){const p=selectedProduct(),scenarios=scenariosFor(p.id);view.innerHTML=head('JOUW AI MEDEWERKER',`De ${p.name} staat <em>al voor jullie klaar.</em>`,`${p.baseProduct===p.name?'Persoonlijk':'Gebouwd op '+p.baseProduct+' en persoonlijk'} ingericht vanuit alles wat in Consult A + B is begrepen.`, `<a class="button" href="/voorstel">Bekijk voorstel</a>`)+`<section class="agent-picker"><div><span class="metric-label">BEKIJK MOGELIJKE INRICHTING</span><strong>De consultanalyse kiest straks automatisch de beste rol.</strong></div><div class="subnav">${data.products.filter(x=>['inbox','followup','phone'].includes(x.id)).map(x=>`<button class="button ${x.selected?'':'secondary'}" data-action="select-product" data-id="${x.id}">${x.name}</button>`).join('')}</div></section><section class="security-strip"><div>${badge('Preview Sandbox','green')}<strong>Geïsoleerde demo-omgeving</strong></div><span>Geen echte klantdata</span><span>Geen externe writes</span><span>Verloopt ${new Date(data.preview.expiresAt).toLocaleDateString('nl-NL')}</span></section><div class="page-grid two preview-summary"><article class="item-card"><span class="metric-label">PERSOONLIJK INGERICHT</span>${p.capabilities.map(x=>`<div class="micro-row"><span>✓</span>${x}</div>`).join('')}</article><article class="item-card"><span class="metric-label">VEILIGHEIDSGRENZEN</span>${data.preview.restrictions.map(x=>`<div class="micro-row"><span>—</span>${x}</div>`).join('')}</article></div><section class="understood-strip"><div><span class="metric-label">GEBRUIKTE CONTEXT</span><strong>${data.understanding.sources.length} bronnen · ${data.understanding.openAssumptions.length} open aannames</strong></div><p>${data.understanding.summary}</p><a class="text-link" href="/requirements">Bekijk alles wat is begrepen →</a></section><div class="subnav">${scenarios.map((x,i)=>`<button class="button ${i?'secondary':''}" data-action="scenario" data-id="${i}">${x}</button>`).join('')}</div><section class="card"><div class="card-head"><div><div class="eyebrow">SCENARIO</div><h2 id="scenarioTitle">${scenarios[0]}</h2></div>${badge('Veilige simulatie')}</div><div class="page-grid two"><div class="item-card"><h3>Gespreksverloop</h3><div id="scenarioMessages"><p class="muted">Start het scenario om de route van deze ${p.name} te bekijken.</p></div><div class="actions">${button('Start scenario','play-scenario','','')}</div></div><div class="item-card"><h3>Gesimuleerde systeemacties</h3><div id="scenarioActions" class="checklist"><p class="muted">Nog geen acties uitgevoerd.</p></div></div></div></section>`}
function scenariosFor(id){return id==='inbox'?['Voorraadvraag via WhatsApp','Servicevraag per e-mail','Websitechat kwalificeren','Boze klant','Menselijke overdracht']:id==='followup'?['Nieuwe platformlead','Offerte opvolgen','No-show herstellen','Bezwaar herkennen','Afmelding verwerken']:id==='phone'?['Inkomende verkoopcall','Werkplaatsafspraak','Spoedtriage','Buiten openingstijd','Menselijke overdracht']:['Onderhoudsafspraak','Proefrit plannen','Voorraadvraag','Boze klant','Menselijke overdracht']}
function requirements(){const u=data.understanding,p=selectedProduct();view.innerHTML=head('CONSULT A + B','Dit hebben we <em>begrepen.</em>','De onderbouwing van jullie voorgestelde AI Medewerker. Controleer inzichten en open aannames vóór activatie.',`<a class="button" href="/demo">Bekijk ${p.name}</a>`)+`<section class="understanding-hero"><span class="metric-label">SAMENVATTING</span><h2>${u.summary}</h2><div class="source-list">${u.sources.map(x=>`<span>${x}</span>`).join('')}</div></section><div class="understanding-grid"><article class="card"><div class="eyebrow">KNELPUNTEN</div>${insightRows(u.challenges)}</article><article class="card"><div class="eyebrow">DOELEN</div>${insightRows(u.goals)}</article><article class="card"><div class="eyebrow">KANALEN</div><div class="tag-cloud">${u.channels.map(x=>`<span>${x}</span>`).join('')}</div><div class="eyebrow spaced">SYSTEMEN</div><div class="tag-cloud">${u.systems.map(x=>`<span>${x}</span>`).join('')}</div></article><article class="card"><div class="eyebrow">VEILIGHEID & GRENZEN</div>${u.boundaries.map(x=>`<div class="micro-row"><span>—</span>${x}</div>`).join('')}</article></div><section class="card assumption-card"><div class="card-head"><div><div class="eyebrow">OPEN AANNAMES</div><h2>Nog door jullie te bevestigen</h2></div>${badge(`${u.openAssumptions.length} open`,'orange')}</div>${u.openAssumptions.map(x=>`<div class="micro-row"><span>?</span>${x}</div>`).join('')}</section><section class="card"><div class="card-head"><div><div class="eyebrow">CONCRETE REQUIREMENTS</div><h2>Controleerbare bouwregels</h2></div></div><div class="checklist">${data.requirements.map(r=>`<div class="check-row"><button class="check ${r.status==='confirmed'?'done':''}" data-action="requirement" data-id="${r.id}">${r.status==='confirmed'?'✓':'○'}</button><div><strong>${r.title}</strong><small>${r.comment||'Afkomstig uit de consultanalyse'}</small></div>${badge(r.status==='confirmed'?'Bevestigd':'Controleren',r.status==='confirmed'?'green':'orange')}</div>`).join('')}</div></section><section class="card product-section"><div class="card-head"><div><div class="eyebrow">PRODUCTMATCH</div><h2>Waarom deze combinatie?</h2></div>${badge(`${p.name} geselecteerd`,'green')}</div><div class="product-grid">${data.products.filter(x=>x.recommended).map(productCard).join('')}</div></section>`}
function proposal(){const c=data.commercial,p=selectedProduct();view.innerHTML=head('PERSOONLIJK VOORSTEL',`${p.name}: van contact naar <em>concrete actie.</em>`,'Voorstel '+c.proposalVersion+' · geldig tot '+new Date(c.validUntil).toLocaleDateString('nl-NL')+'. Jullie persoonlijke AI Medewerker staat al klaar.',`<a class="button secondary" href="/demo">Test eerst de agent</a>`)+`<section class="activation-line"><span class="step-on">1 · Preview gereed</span><span>2 · Akkoord</span><span>3 · Betaling</span><span>4 · Implementatie actief</span></section><div class="page-grid"><article class="item-card"><span class="metric-label">WAAROM DEZE ROL</span><h3>${p.name}</h3><p>${p.promise}</p><a class="text-link" href="/requirements">Bekijk onderbouwing →</a></article><article class="item-card"><span class="metric-label">INRICHTING</span><h3>${p.baseProduct}</h3><p>${p.channels.join(', ')} · testomgeving · menselijke fallback.</p><strong>2–4 weken</strong></article><article class="item-card offer-card"><span class="metric-label">INVESTERING</span><h3>Scale</h3><p>Eenmalig €${c.priceSetup.toLocaleString('nl-NL')} · €${c.priceMonthly.toLocaleString('nl-NL')} per maand · usage apart.</p><div class="actions"><a class="button" href="/documenten">Controleer en activeer</a></div></article></div><article class="card table-card"><div class="card-head"><div><div class="eyebrow">TRANSPARANT</div><h2>Dit leveren we</h2></div>${badge(`${p.name} preview gereed`,'green')}</div><div class="checklist">${p.capabilities.map(x=>`<div class="check-row"><span class="check done">✓</span><div><strong>${x}</strong><small>Persoonlijk ingericht vanuit de bevestigde requirements.</small></div></div>`).join('')}<div class="check-row"><span class="check done">✓</span><div><strong>Testen, livegang en monitoring</strong><small>Productie blijft geblokkeerd tot kritieke gates slagen.</small></div></div></div></article><section class="card product-section"><div class="card-head"><div><div class="eyebrow">UITBREIDBAAR</div><h2>Alle Autopilots-producten</h2></div><span class="mini">Alleen toevoegen wanneer de klantreis dit vraagt</span></div><div class="product-grid">${data.products.map(productCard).join('')}</div></section>`}
function documents(){const l=data.legal;view.innerHTML=head('VOORWAARDEN & PRIVACY','Alles helder vóór jullie <em>activeren.</em>','Lees de actuele documenten volledig. We bewaren het versienummer en acceptatiebewijs bij jullie voorstel.')+`<section class="legal-layout"><div class="legal-docs"><article class="legal-document"><span class="metric-label">VERSIE ${l.terms.version}</span><h2>Algemene Voorwaarden</h2><p>Hierin staan de dienstverlening, scope, betaling, verantwoordelijkheden, gebruikslimieten, aansprakelijkheid, looptijd en beëindiging transparant beschreven.</p><details><summary>Lees de belangrijkste bepalingen</summary><div class="legal-copy"><h3>Dienstverlening en scope</h3><p>Autopilots configureert, test en beheert de overeengekomen AI Medewerker. Productieacties worden pas toegestaan na onboarding, succesvolle tests en livegoedkeuring.</p><h3>Verantwoordelijkheden</h3><p>De klant blijft verantwoordelijk voor aangeleverde informatie, toegangen en bedrijfsspecifieke beslissingen. Autopilots bewaakt de technische werking binnen de overeengekomen scope.</p><h3>Beperkingen</h3><p>De AI Medewerker mag geen bindende toezeggingen buiten de ingestelde bevoegdheden doen en draagt bij twijfel over aan een mens.</p></div></details><a class="text-link" href="#terms">Open volledige demo-versie →</a></article><article class="legal-document"><span class="metric-label">VERSIE ${l.privacy.version}</span><h2>Privacyverklaring</h2><p>Welke gegevens we gebruiken, waarom, hoelang, met welke providers en welke rechten betrokkenen hebben.</p><details><summary>Lees hoe gegevens worden verwerkt</summary><div class="legal-copy"><h3>Doel en minimale gegevens</h3><p>Gegevens worden alleen gebruikt voor voorstel, implementatie, beveiliging, support en de overeengekomen AI-dienstverlening.</p><h3>Bewaren en verwijderen</h3><p>Bewaartermijnen worden per datatype vastgelegd. De klant kan export, correctie of verwijdering aanvragen.</p><h3>Automatisering</h3><p>Gevoelige of onzekere beslissingen worden niet zelfstandig uitgevoerd maar naar een bevoegd persoon gestuurd.</p></div></details><a class="text-link" href="#privacy">Open volledige demo-versie →</a></article><article class="legal-document"><span class="metric-label">VERSIE ${l.dpa.version}</span><h2>Verwerkersovereenkomst</h2><p>Bevat rollen, beveiligingsmaatregelen, subverwerkers, incidentafhandeling, bewaartermijnen en verwijdering.</p><details><summary>Lees beveiliging en subverwerkers</summary><div class="legal-copy"><h3>Beveiliging</h3><p>Tenant-isolatie, encryptie, minimale rechten, auditlogging, gecontroleerde uploads en secrets management zijn verplicht.</p><h3>Subverwerkers</h3><p>Ingezette AI-, hosting-, voice- en integratieproviders worden transparant in een actueel register vermeld.</p></div></details><a class="text-link" href="#dpa">Open volledige demo-versie →</a></article></div><aside class="accept-card"><div class="eyebrow">ACTIVERING</div><h2>Controle en akkoord</h2>${legalCheck('terms','Ik ga akkoord met de Algemene Voorwaarden',l.terms.accepted)}${legalCheck('privacy','Ik bevestig dat ik de Privacyverklaring kon lezen',l.privacy.acknowledged)}${legalCheck('dpa','Ik ga akkoord met de Verwerkersovereenkomst',l.dpa.accepted)}<hr>${legalCheck('marketing','Ik ontvang graag productupdates (optioneel)',l.marketing.accepted)}<p class="mini">Acceptaties worden gekoppeld aan voorstel ${data.commercial.proposalVersion}, documentversie, account en tijdstip.</p><div class="actions"><a class="button ${legalReady()?'':'is-disabled'}" href="${legalReady()?'/afrekenen':'#'}">Verder naar veilig afrekenen</a></div></aside></section>`}
function legalCheck(type,label,checked){return `<label class="legal-check"><input type="checkbox" data-action="legal" data-id="${type}" ${checked?'checked':''}><span>${label}</span></label>`}
function legalReady(){return data.legal.terms.accepted&&data.legal.privacy.acknowledged&&data.legal.dpa.accepted}
function gatedCheckout(){view.innerHTML=head('VEILIG AFREKENEN','Controleer eerst de <em>documenten.</em>','Afrekenen blijft geblokkeerd totdat alle verplichte documentversies zijn geaccepteerd. Marketingtoestemming blijft optioneel.',`<a class="button" href="/documenten">Naar voorwaarden</a>`)+`<section class="locked-card"><div class="lock-icon">AP</div><h2>Checkout nog niet beschikbaar</h2><p>De implementatie wordt pas na akkoord en een geverifieerde betaling geactiveerd.</p></section>`}
function gatedPaymentSuccess(){view.innerHTML=head('BETALINGSSTATUS','Nog geen geverifieerde <em>betaling.</em>','Deze bevestigingspagina wordt pas beschikbaar na een geldige checkout.',`<a class="button" href="/documenten">Start activatie</a>`)+`<section class="locked-card"><div class="lock-icon">AP</div><h2>Implementatie niet geactiveerd</h2><p>De Secure Data Room en implementatieworkflow blijven gesloten.</p></section>`}
function checkout(){if(data.commercial.status==='implementation_activated')return paid();if(!legalReady())return gatedCheckout();const p=selectedProduct();view.innerHTML=head('VEILIG AFREKENEN','Activeer jullie <em>implementatie.</em>','Dit scherm simuleert een gehoste checkout. Er worden geen echte betaalgegevens gevraagd of verwerkt.')+`<section class="checkout-grid"><article class="checkout-card"><div class="secure-mark">✓</div><div><div class="eyebrow">VEILIGE CHECKOUT DEMO</div><h2>Scale · ${p.name}</h2><p>${p.promise} Inclusief configuratie, testomgeving, koppelingen, livegang en monitoring.</p></div><div class="price-row"><span>Eenmalige implementatie</span><strong>€${data.commercial.priceSetup.toLocaleString('nl-NL')}</strong></div><div class="price-row"><span>Abonnement vanaf activatie</span><strong>€${data.commercial.priceMonthly.toLocaleString('nl-NL')} / maand</strong></div><div class="price-row muted"><span>Gebruikskosten</span><strong>Op nacalculatie</strong></div><div class="legal-proof">✓ Voorwaarden ${data.legal.terms.version} geaccepteerd<br>✓ Privacyverklaring ${data.legal.privacy.version} bevestigd<br>✓ Verwerkersovereenkomst ${data.legal.dpa.version} geaccepteerd</div><button class="button checkout-button" data-action="payment">Simuleer geverifieerde betaling</button><span class="mini">In productie opent hier Stripe Checkout. Alleen een ondertekende webhook activeert de implementatie.</span></article><aside class="checkout-side"><h3>Na betaling</h3><div class="micro-row"><span>1</span>Secure Data Room opent</div><div class="micro-row"><span>2</span>Implementatie-workflow start</div><div class="micro-row"><span>3</span>Agents krijgen begrensde taken</div><div class="micro-row"><span>4</span>Productie blijft geblokkeerd tot livegoedkeuring</div></aside></section>`}
function paid(){if(data.commercial.status!=='implementation_activated')return gatedPaymentSuccess();view.innerHTML=head('IMPLEMENTATIE GEACTIVEERD','Welkom bij <em>Autopilots.</em>','De demo-betaling is geverifieerd en de beveiligde implementatieomgeving is geopend.')+`<section class="success-card"><div class="success-icon">✓</div><div><span class="metric-label">REFERENTIE ${data.commercial.paymentReference||'demo_checkout_verified'}</span><h2>Jullie AI Medewerker gaat de implementatiefase in.</h2><p>Productierechten blijven uitgeschakeld totdat informatie, koppelingen, tests en livegoedkeuring compleet zijn.</p><div class="actions"><a class="button" href="/secure-data-room">Open veilige onboarding</a><a class="button secondary" href="/demo">Bekijk AI Medewerker</a></div></div></section>`}
function secureDataRoom(){const room=data.dataRoom;if(room.status!=='open'){view.innerHTML=head('VEILIGE ONBOARDING','Secure Data Room <em>vergrendeld.</em>','Na akkoord en betaling opent de afgeschermde omgeving voor documenten, gegevens en koppelingen.',`<a class="button" href="/voorstel">Bekijk voorstel</a>`)+`<section class="locked-card"><div class="lock-icon">⌾</div><h2>Geen gevoelige informatie vóór activatie</h2><p>De preview gebruikt uitsluitend gecontroleerde demodata. API-sleutels, productiedocumenten en klantlijsten worden hier niet vooraf gevraagd.</p></section>`;return}const done=data.onboarding.filter(x=>x.status==='done').length;view.innerHTML=head('SECURE DATA ROOM','Lever informatie <em>veilig aan.</em>','Versleuteld, per organisatie geïsoleerd en volledig gelogd. Deel nooit credentials via e-mail.')+`<section class="security-strip"><div>${badge('Vertrouwelijk','green')}<strong>Tenant: Curaçao Auto Center</strong></div><span>Encryptie actief</span><span>Uploadscan actief</span><span>Agents zien geen secrets</span></section><div class="room-tabs"><a href="#gegevens">Gegevens</a><a href="#documenten">Documenten</a><a href="#toegangen">Toegangen</a></div><section class="room-section" id="gegevens"><div class="card-head"><div><div class="eyebrow">GESTRUCTUREERDE GEGEVENS</div><h2>Implementatiegegevens</h2></div>${badge(`${done}/${data.onboarding.length} checklist`)}</div><div class="page-grid">${room.fields.map(f=>`<article class="item-card"><span class="metric-label">${f.sensitivity==='personal'?'PERSOONSGEGEVEN':'NORMAAL'}</span><div class="field"><label for="room-${f.id}">${f.label}</label><input id="room-${f.id}" value="${escapeHtml(f.value)}" data-room-field="${f.id}" placeholder="Veilig invoeren"></div><div class="actions">${button('Versleuteld opslaan','save-field',f.id)}</div></article>`).join('')}</div></section><section class="room-section" id="documenten"><div class="eyebrow">BESCHERMDE UPLOAD</div><h2>Documenten</h2><div class="upload-zone"><label for="demoFile"><strong>PDF, DOCX, CSV of TXT</strong></label><p>Bestanden worden hernoemd, geïsoleerd, versleuteld en eerst in quarantaine gescand.</p><input id="demoFile" type="file" accept=".pdf,.docx,.csv,.txt"><button class="button secondary" data-action="upload-document">Scan demo-upload</button></div><div class="file-list">${room.documents.length?room.documents.map(d=>`<div class="file-row"><strong>${escapeHtml(d.name)}</strong>${badge('Veilig gescand','green')}<span class="mini">Versleuteld · tenant-isolatie</span></div>`).join(''):'<p class="muted">Nog geen documenten aangeleverd.</p>'}</div></section><section class="room-section" id="toegangen"><div class="eyebrow">SECRETS VAULT</div><h2>Handmatige credential</h2><p class="muted">Gebruik OAuth waar mogelijk. Alleen voor systemen zonder OAuth kan een credential direct naar de vault worden verzonden.</p><div class="secret-form"><div class="field"><label for="secretLabel">Naam van de toegang</label><input id="secretLabel" placeholder="Bijvoorbeeld Dealer CRM API"></div><div class="field"><label for="secretValue">Secret</label><input id="secretValue" type="password" autocomplete="new-password" placeholder="Wordt nooit opnieuw getoond"></div><button class="button" data-action="store-secret">Direct naar vault</button></div><div class="file-list">${room.secrets.map(s=>`<div class="file-row"><strong>${escapeHtml(s.label)}</strong>${badge('Opgeslagen','green')}<span class="mini">${s.masked} · niet leesbaar voor agents</span></div>`).join('')}</div></section>`}
function escapeHtml(value=''){return String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function integrations(){view.innerHTML=head('VEILIGE KOPPELINGEN','Verbind alleen wat <em>nodig is.</em>','OAuth waar mogelijk. Test en productie blijven strikt gescheiden.')+`<div class="page-grid">${data.integrations.map(x=>`<article class="item-card"><div class="item-top"><span class="metric-label">${x.environment}</span>${badge(x.status,x.status==='connected'?'green':x.status==='review'?'orange':'')}</div><h3>${x.name}</h3><p>${x.scope}</p><span class="mini">Health: ${x.health} · AI ziet nooit de ruwe secret</span><div class="actions">${button(x.status==='connected'?'Opnieuw verbinden':'OAuth simuleren','integration-connect',x.id)}${button('Test verbinding','integration-test',x.id)}</div></article>`).join('')}</div>`}
function tests(){const gates=[['Requirements bevestigd',data.requirements.every(item=>item.status==='confirmed')],['Juridische versies geaccepteerd',legalReady()],['Sandboxbetaling geverifieerd',data.commercial.status==='implementation_activated'],['Testkoppelingen gezond',data.integrations.filter(item=>item.status==='connected').every(item=>item.health==='healthy')]],passed=gates.filter(([,ok])=>ok).length,score=Math.round(passed/gates.length*100);view.innerHTML=head('READINESS GATES',`De gecontroleerde route is <em>${score}% gereed.</em>`,'Deze score komt rechtstreeks uit vier zichtbare demo-gates. Productie blijft altijd geblokkeerd tot een bevoegde operator goedkeurt.')+`<div class="page-grid"><article class="item-card"><div class="score-ring" style="--score:${score}%"><strong>${score}%</strong></div><h3>Gate score</h3><p>${passed} van ${gates.length} controlepunten zijn aantoonbaar geslaagd.</p></article>${gates.map(([name,ok])=>`<article class="item-card"><div class="item-top"><span class="metric-label">CONTROLEPUNT</span>${badge(ok?'Geslaagd':'Open',ok?'green':'orange')}</div><h3>${name}</h3><p>${ok?'Bewijs is aanwezig in de huidige demo-workflow.':'Deze gate blokkeert de volgende risicovolle stap.'}</p></article>`).join('')}</div>`}
function activity(){view.innerHTML=head('AUDIT TRAIL','Iedere belangrijke actie <em>traceerbaar.</em>','Veilige uitleg zonder secrets of interne modelredeneringen.')+`<article class="card"><div class="audit-row"><strong>Datum</strong><strong>Actie</strong><strong>Actor</strong><strong>Risico</strong></div>${data.audit.map(x=>`<div class="audit-row"><span>${new Date(x.createdAt).toLocaleString('nl-NL')}</span><div><strong>${x.action}</strong><br><span class="mini">${x.reason}</span></div><span>${x.actor}</span>${badge('Niveau '+x.risk)}</div>`).join('')}</article>`}
function control(){const activated=data.commercial.status==='implementation_activated',pending=data.approvals.filter(item=>item.status==='pending').length,customerCount=data.organization?1:0,implementationCount=data.implementation?.status==='active'?1:0;view.innerHTML=head('AUTOPILOTS COMMAND','Operationeel zicht op <em>elk autonoom systeem.</em>','Een bestuurbare cockpit voor implementaties, agents, risico en menselijke interventies.',badge('Live sandbox signal','green'))+workflowRadar()+workflowVector()+`<section class="grid metrics hud-metrics"><article class="metric"><span class="metric-label">Totaal klanten</span><strong>${customerCount}</strong><small>organisaties in portfolio</small><i class="metric-pulse"></i></article><article class="metric"><span class="metric-label">Veilig geactiveerd</span><strong>${data.metrics.verifiedActivations}</strong><small>alle gates geslaagd</small><i class="metric-pulse"></i></article><article class="metric"><span class="metric-label">Menselijke aandacht</span><strong>${data.metrics.humanAttention}</strong><small>taken en approvals</small><i class="metric-pulse alert"></i></article><article class="metric"><span class="metric-label">Gemeten kosten</span><strong>${formatMoney(data.metrics.totalCostCents)}</strong><small>append-only ledger</small><i class="metric-pulse"></i></article></section><article class="card portfolio-status"><div class="card-head"><div><span class="metric-label">PORTFOLIO STATUS</span><h2>Operationeel overzicht</h2><p class="muted">Geaggregeerde status van alle klanten en implementaties in deze omgeving.</p></div>${badge(pending?`${pending} approval open`:'Geen approvals gereed',pending?'orange':'green')}</div><div class="portfolio-readout"><span><b>${customerCount}</b>klanten totaal</span><span><b>${implementationCount}</b>implementaties actief</span><span><b>${activated?0:1}</b>previews in voorbereiding</span><span><b>${data.metrics.humanAttention}</b>interventies nodig</span></div><div class="actions"><a class="button" href="/control-center/implementaties/impl_001">Bekijk implementaties</a><a class="button secondary" href="/control-center/approvals">Open approvals</a></div></article>`}
function implementation(){const next={integration_setup:'ready_to_build',ready_to_build:'testing',testing:'ready_for_review',ready_for_review:'menselijke livegoedkeuring',ready_for_authorized_activation:'externe activatie blijft geblokkeerd'}[data.implementation.state];view.innerHTML=head('IMPLEMENTATIE',`${selectedProduct().name} <em>delivery.</em>`,'Requirements, agents, tests en approvals in één veilige tijdlijn.')+`<div class="page-grid"><article class="item-card"><span class="metric-label">Lifecycle</span><h3>${data.implementation.state}</h3><p>Volgende geldige stap: ${next||'menselijke controle'}.</p>${['ready_for_review','ready_for_authorized_activation'].includes(data.implementation.state)?badge(data.implementation.state==='ready_for_review'?'Mens vereist':'Approval vastgelegd',data.implementation.state==='ready_for_review'?'orange':'green'):button('Simuleer volgende stap','lifecycle')}</article><article class="item-card"><span class="metric-label">Workflowversie</span><h3>${data.workflow.version}</h3><p>${data.workflow.currentStep} · geen externe writes.</p></article><article class="item-card"><span class="metric-label">Gemeten kosten</span><h3>${formatMoney(data.metrics.totalCostCents)}</h3><p>${data.executions.length} gelogde uitvoeringen in deze demosessie.</p></article></div>`}
function tasks(){view.innerHTML=head('HUMAN TASK INBOX','Alleen werk dat een mens <em>vereist.</em>','Goedkeuren, aanpassen, afwijzen of escaleren met alle context erbij.')+`<div class="page-grid">${data.tasks.map(x=>`<article class="item-card"><div class="item-top">${badge(x.priority,'orange')}${badge(x.status,x.status==='open'?'':'green')}</div><h3>${x.title}</h3><p>${x.impact}</p><span class="mini">Bewijs: ${x.evidence}</span><div class="actions">${button('Goedkeuren','task',x.id)}${button('Afwijzen','task-reject',x.id)}${button('Escaleren','task-escalate',x.id,'danger')}</div></article>`).join('')}</div>`}
function approvals(){const pending=data.approvals.filter(item=>item.status==='pending').length,locked=data.approvals.filter(item=>item.status==='not_ready').length;view.innerHTML=head('APPROVAL CENTER','Risicovolle acties wachten op <em>een mens.</em>','Beslis met doel, bewijs, uitgaande data, blast radius en een vastgezette contextversie.')+`<section class="approval-layout"><div class="page-grid approval-cards">${data.approvals.map(item=>`<article class="item-card"><div class="item-top">${badge(item.risk,'orange')}${badge(item.status,item.status==='approved'?'green':item.status==='pending'?'orange':'')}</div><h3>${item.type}</h3><p>${item.rationale}</p><div class="micro-row"><span>→</span><strong>Doel:</strong>&nbsp;${item.target}</div><div class="micro-row"><span>→</span><strong>Blast radius:</strong>&nbsp;${item.blastRadius}</div><div class="micro-row"><span>→</span><strong>Uitgaande data:</strong>&nbsp;${item.outgoingData}</div><span class="mini">Contextversie ${item.contextVersion} · bewijs: ${item.evidence.join(', ')}</span><div class="actions">${item.status==='pending'?button('Goedkeuren','approval-approve',item.id)+button('Afwijzen','approval-reject',item.id,'danger'):badge(item.status,item.status==='approved'?'green':'')}</div></article>`).join('')}</div><aside class="risk-monitor"><div class="risk-orbit"><i></i><span><b>R3</b>HUMAN GATE</span></div><div class="risk-readout"><span><b>${pending}</b>beslissingen gereed</span><span><b>${locked}</b>geblokkeerd door gates</span><span><b>${data.preview.externalWrites?'ON':'OFF'}</b>externe writes</span><span><b>V${data.approvals[0]?.contextVersion||1}</b>context lock</span></div><p>Geen activatie zonder actuele context, aantoonbaar bewijs en een bevoegde menselijke beslissing.</p></aside></section>`}
function agents(){view.innerHTML=head('AGENT CONTROL ROOM','Agents werken binnen <em>vaste grenzen.</em>','Zie acties, tools, budgetten en approvals. Geen verborgen redeneringen.')+`<div class="page-grid">${data.agents.map(x=>`<article class="item-card"><div class="item-top"><span class="agent-status ${x.status}">${x.status}</span>${badge(x.version)}</div><h3>${x.name}</h3><p>${x.task}</p><span class="mini">Tools: ${x.tools.join(', ')} · budget ${x.budget}</span><div class="actions">${x.status==='stopped'?badge('Menselijke heractivatie vereist','orange'):button(x.status==='paused'?'Hervatten':'Pauzeren','agent',x.id)+button('Kill switch','agent-kill',x.id,'danger')}</div></article>`).join('')}</div>`}
async function command(action,payload={}){const response=await fetch(`/api/v1/demo/command?${companyApiQuery}`,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({action,payload})});const result=await response.json();if(response.status===401){location.replace('/login');return false}if(!response.ok){toast(result.error||'Actie kon niet worden verwerkt.',true);return false}const refreshed=await fetch(`/api/v1/demo?${companyApiQuery}`);if(refreshed.status===401){location.replace('/login');return false}data=await refreshed.json();toast('Actie veilig verwerkt en gelogd.');render();return true}
document.addEventListener('click',async event=>{const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;try{if(action==='company-toggle'){const menu=document.querySelector('.company-menu'),expanded=target.getAttribute('aria-expanded')==='true';target.setAttribute('aria-expanded',String(!expanded));menu.hidden=expanded;return}if(action==='company-select')return location.href=`/control-center?company=${encodeURIComponent(id)}`;if(action==='logout'){await fetch('/api/v1/session/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});return location.replace('/login')}if(action==='reset')return command('demo.reset');if(action==='login-role'){loginRole=id;document.querySelectorAll('[data-action="login-role"]').forEach(x=>x.classList.toggle('active',x===target));const internalRole=id==='internal';document.querySelector('#demoEmail').value=internalRole?'operator@autopilots.example':'demo@curacao-auto.example';const code=document.querySelector('#demoCode');if(code)code.value=internalRole?'autopilots-internal':'autopilots-demo';return}if(action==='requirement')return command('requirement.confirm',{id});if(action==='onboarding')return command('onboarding.toggle',{id});if(action==='integration-connect')return command('integration.connect',{id});if(action==='integration-test')return command('integration.test',{id});if(action==='task')return command('task.resolve',{id,decision:'approved'});if(action==='task-reject')return command('task.resolve',{id,decision:'rejected'});if(action==='task-escalate')return command('task.resolve',{id,decision:'escalated'});if(action==='approval-approve'||action==='approval-reject'){const item=data.approvals.find(approval=>approval.id===id);return command('approval.decide',{id,decision:action==='approval-approve'?'approved':'rejected',contextVersion:item.contextVersion})}if(action==='agent')return command('agent.toggle',{id});if(action==='agent-kill'){if(confirm('Demo-agent stoppen? Deze actie wordt in het audit trail gezet.'))return command('agent.kill',{id,reason:'Kill switch'})}if(action==='select-product')return command('product.select',{id});if(action==='payment'){const paid=await command('payment.complete',{reference:'demo_checkout_verified'});if(paid)return location.href='/betaling-geslaagd';return}if(action==='save-field'){const input=document.querySelector(`[data-room-field="${id}"]`);return command('dataroom.field',{id,value:input?.value||''})}if(action==='upload-document'){const file=document.querySelector('#demoFile')?.files?.[0];if(!file)throw new Error('Kies eerst een demobestand');return command('dataroom.document',{name:file.name})}if(action==='store-secret'){const label=document.querySelector('#secretLabel')?.value;const secret=document.querySelector('#secretValue')?.value;if(!label||!secret)throw new Error('Vul naam en secret in');document.querySelector('#secretValue').value='';return command('dataroom.secret',{label,value:secret})}if(action==='proposal')return location.href='/documenten';if(action==='play-scenario')return playScenario();if(action==='scenario'){document.querySelector('#scenarioTitle').textContent=scenariosFor(selectedProduct().id)[Number(id)];toast('Scenario geselecteerd.')}if(action==='test-filter')toast(`Filter actief: ${id}.`);if(action==='lifecycle')return command('lifecycle.advance')}catch(error){toast(error.message,true)}});
document.addEventListener('change',async event=>{const input=event.target.closest('[data-action="legal"]');if(!input)return;try{await command('legal.accept',{type:input.dataset.id,accepted:input.checked})}catch(error){toast(error.message,true)}});
document.addEventListener('submit',async event=>{if(event.target.id==='mfaForm'){event.preventDefault();const error=document.querySelector('#mfaError'),submit=event.target.querySelector('[type="submit"]'),code=document.querySelector('#mfaCode')?.value.trim();error.hidden=true;submit.disabled=true;try{if(!pendingMfa)throw new Error('De tijdelijke inlogsessie is verlopen.');const response=await fetch('/api/v1/session/mfa/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...pendingMfa,code})});const result=await response.json();if(!response.ok)throw new Error(result.error||'De authenticatorcode kon niet worden bevestigd.');pendingMfa=null;return location.replace('/control-center/portfolio')}catch(mfaError){error.textContent=mfaError.message;error.hidden=false;submit.disabled=false}return}if(event.target.id!=='loginForm')return;event.preventDefault();const email=document.querySelector('#demoEmail')?.value.trim(),code=document.querySelector('#demoCode')?.value,error=document.querySelector('#loginError'),submit=event.target.querySelector('[type="submit"]'),managed=authCapabilities.provider==='supabase';error.hidden=true;submit.disabled=true;try{const response=await fetch('/api/v1/session/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(managed?{email}:{email,code,role:loginRole})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Inloggen is niet gelukt');if(managed){event.target.innerHTML=`<div class="eyebrow">INLOGLINK VERSTUURD</div><h3>Controleer je e-mail</h3><p>${escapeText(result.message)}</p><span class="mini">De link is eenmalig en brengt je terug naar deze beveiligde omgeving.</span>`;return}location.href=result.user.role==='internal'?'/control-center':'/'}catch(loginError){error.textContent=loginError.message;error.hidden=false;submit.disabled=false}});
async function playScenario(){const box=document.querySelector('#scenarioMessages'),actions=document.querySelector('#scenarioActions'),product=selectedProduct();const scripts={inbox:[['Klant','Is de Audi A4 nog beschikbaar?'],[product.name,'Ja. Wilt u ook een proefrit plannen of eerst informatie over inruil ontvangen?'],['Klant','Graag zaterdag een proefrit.'],[product.name,'Ik heb uw voorkeur vastgelegd en controleer de beschikbare momenten.']],followup:[['Lead','Ik heb gisteren een aanvraag voor de Audi A4 gedaan.'],[product.name,'Dank u. Wilt u een proefrit plannen of heeft u eerst een vraag over de auto?'],['Lead','Een proefrit op zaterdag graag.'],[product.name,'Ik controleer de agenda en zet uw voorkeursmoment klaar.']],phone:[['Beller','Goedemiddag, ik wil een werkplaatsafspraak maken.'],[product.name,'Natuurlijk. Om welke auto en welk type onderhoud gaat het?'],['Beller','Een Volkswagen Golf met een onderhoudsmelding.'],[product.name,'Ik bevestig eerst uw contactgegevens en controleer daarna de agenda.']],service:[['Klant','Ik wil graag een serviceafspraak maken.'],[product.name,'Natuurlijk. Ik controleer eerst de auto en uw contactgegevens.'],['Klant','Het gaat om mijn Volkswagen Golf.'],[product.name,'Dinsdag om 10:30 is beschikbaar. Zal ik die reserveren?']]};box.innerHTML='';for(const [speaker,text] of scripts[product.id]||scripts.service){const item=document.createElement('p');item.innerHTML=`<strong>${speaker}</strong><br>${text}`;box.append(item);await new Promise(r=>setTimeout(r,350))}actions.innerHTML=(product.id==='followup'?['Leadbron herkend','Reactie geclassificeerd','Agenda gecontroleerd','Pipeline-concept voorbereid']:product.id==='inbox'?['Kanaal en intentie herkend','Kennis gecontroleerd','Intake aangevuld','CRM-concept voorbereid']:['Vraag herkend','Gegevens bevestigd','Agenda gecontroleerd','CRM-concept voorbereid']).map(x=>`<div class="check-row"><span class="check done">✓</span><strong>${x}</strong></div>`).join('');toast('Scenario voltooid zonder echte externe acties.')}
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.style.background=error?'#9f3826':'';el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2800)}render();
